package org.jlinalg.cli;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;

class CrossmapWorkflowTest {
    @TempDir Path temporary;
    record Result(int code,String output,String error) { }
    Result call(String... args){var out=new ByteArrayOutputStream();var err=new ByteArrayOutputStream();var all=new ArrayList<>(List.of("crossmap-tools"));all.addAll(List.of(args));int code=JLinAlgCli.run(all.toArray(String[]::new),new PrintStream(out,true,StandardCharsets.UTF_8),new PrintStream(err,true,StandardCharsets.UTF_8));return new Result(code,out.toString(StandardCharsets.UTF_8),err.toString(StandardCharsets.UTF_8));}
    @Test void exactProfilesAndHelpReturnWithoutAdmittingUserAnalysis(){var help=call("--help");assertEquals(0,help.code());for(String text:List.of("0.5.2","0.6.3","--request","--verify","--export-runtime-setup","SKIP3","FAIL2","Required action:","Linux","Cell Ranger"))assertTrue(help.output().contains(text),text);var profiles=call("--profiles");assertEquals(0,profiles.code());assertTrue(profiles.output().contains("author_Python37_reproduced\":false"));assertEquals("",profiles.error());}
    @Test void missingRuntimeSkipsDependentConversionWithoutCreatingOutput(){Path target=temporary.resolve("uncreated");var result=call("--request",temporary.resolve("request.json").toString(),"--out",target.toString());assertEquals(3,result.code());assertTrue(result.error().contains("SKIP3 DEPENDENT ANALYSIS SKIPPED"));assertFalse(Files.exists(target));}
    @Test void setupExportPreservesExactSourcesAndCannotOverwrite()throws Exception{Path target=temporary.resolve("setup");assertEquals(0,call("--export-runtime-setup",target.toString()).code());for(String name:List.of("setup.py","health.py","source-lock.json"))assertArrayEquals(CrossmapRuntime.resource(name),Files.readAllBytes(target.resolve(name)));assertTrue(Files.readString(target.resolve("README.txt")).contains("--allow-install"));assertFalse(Files.exists(target.resolve("COMPLETED.json")));byte[] before=Files.readAllBytes(target.resolve("export.json"));assertEquals(2,call("--export-runtime-setup",target.toString()).code());assertArrayEquals(before,Files.readAllBytes(target.resolve("export.json")));assertFalse(Files.exists(target.resolve("FAILURE.txt")));}
    @Test void invalidCombinationsAndMissingResultsNeverFallThrough(){for(String[] args:List.of(new String[]{"--request"},new String[]{"--profiles","extra"},new String[]{"--request","a","--request","b"},new String[]{"--inspect-runtime","home"})){assertEquals(2,call(args).code());}var result=call("--verify",temporary.resolve("missing").toString());assertEquals(2,result.code());assertTrue(result.error().contains("FAIL2"));}
    @Test void sourceVersionOptionsAndUnknownFieldsAreNotSilentlyChanged()throws Exception{var source=request();var s=CrossmapRequest.parse(source,false);assertEquals("0.5.2",s.edition());assertEquals("source-default",s.chromStyle());source.put("chrom_id_style","s");assertThrows(CrossmapRuntime.Unavailable.class,()->CrossmapRequest.parse(source,false));source.put("chrom_id_style","source-default");source.put("unreported_author_option",true);assertThrows(IOException.class,()->CrossmapRequest.parse(source,false));source.remove("unreported_author_option");source.put("edition","latest");assertThrows(CrossmapRuntime.Unavailable.class,()->CrossmapRequest.parse(source,false));}
    @Test void captureAndProcessBoundsMustCoverCompleteEvidence()throws Exception{var source=request();var capture=capture();capture.put("input_bytes",1000000000000L);source.put("capture",capture);assertThrows(IOException.class,()->CrossmapRequest.parse(source,false));var bad=request();var cap2=capture();cap2.put("records",1.5);bad.put("capture",cap2);assertThrows(IOException.class,()->CrossmapRequest.parse(bad,false));}
    @Test void brokenOutputCannotClaimSuccessfulHelp()throws Exception{try(var stream=new PrintStream(new OutputStream(){@Override public void write(int b)throws IOException{throw new IOException("controlled unavailable output");}})){assertEquals(2,CrossmapToolsCli.run(new String[]{"--help"},stream,stream));}}
    private static LinkedHashMap<String,Object> capture(){return new LinkedHashMap<>(Map.of("input_bytes",67108864,"output_bytes",67108864,"records",1000,"bigwig_block_bytes",1048576));}
    private static Map<String,Object> request(){var process=new LinkedHashMap<String,Object>();process.putAll(Map.of("wall_millis",60000,"address_space_bytes",4294967296L,"cpu_seconds",60,"file_bytes",67108864,"open_files",256,"workspace_bytes",201326592,"file_count",1000,"processes",8,"threads",128,"sampled_rss_bytes",1073741824));process.put("monitor_millis",100);var result=new LinkedHashMap<String,Object>();result.putAll(Map.of("schema_version",1,"edition","0.5.2","format","bed","input","/original/input.bed","chain","/original/mapping.chain","input_encoding","plain","chain_encoding","plain","chrom_id_style","source-default","source_build","declared-source","target_build","declared-target"));result.put("unmapped_policy","retain");result.put("process",process);result.put("capture",capture());return result;}
}
